import jQuery from "jquery";

// The rest of the legacy page: tooltips, the FAQ accordion, the gallery
// strip and the sticky header's offset.
export var pageChrome = {
    init: function ($container, config) {
        $container.find("[data-tooltip]").each(function () {
            var $el = jQuery(this);
            $el.attr("title", $el.attr("data-tooltip")).attr("aria-label", $el.attr("data-tooltip"));
        });
        $container.find(".pp-gallery img").each(function (i) {
            jQuery(this).attr("alt", config.name + " – " + (i + 1));
        });
        $container.on("click", ".pp-faq-q", function () {
            var $question = jQuery(this);
            var open = $question.attr("aria-expanded") === "true";
            $question.attr("aria-expanded", String(!open)).next(".pp-faq-a").toggle(!open);
        });
        var $table = $container.find("#rooms-table");
        $container.find(".pp-sticky").attr("data-offset", Math.round($table.offset().top));
        $container.find(".pp-nav a").on("click", function (event) {
            event.preventDefault();
            jQuery(this).addClass("pp-nav-active").parent().siblings().find("a").removeClass("pp-nav-active");
        });
    },
};
