// Price formatting as the legacy scripts do it, without Intl.
export function formatPrice(amount, currencySymbol) {
    var rounded = Math.round(amount);
    var text = String(rounded).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return currencySymbol + text;
}

export function template(source, data) {
    return source.replace(/\{\{(\w+)\}\}/g, function (match, key) {
        return data[key] === undefined ? "" : String(data[key]);
    });
}
