import jQuery from "jquery";

// Reports each room selection change with the page's tracking context.
export var priceTracking = {
    init: function ($container, config) {
        var context = { propertyId: config.propertyId, nights: config.nights, page: "hotel" };
        jQuery(document).off("rooms:selection.tracking").on("rooms:selection.tracking", function (event, rows) {
            var selected = jQuery.map(rows, function (row) {
                return row.quantity ? { b: row.blockId, q: row.quantity, p: row.price } : null;
            });
            window.TravelLegacy.sink.push(JSON.stringify(jQuery.extend({ event: "room_selection.changed", selected: selected, rows: rows.length }, context)));
            if (window.TravelLegacy.sink.length > 20)
                window.TravelLegacy.sink.splice(0, 10);
        });
    },
};
