import jQuery from "jquery";
import { formatPrice, template } from "./format.js";

var LINE = '<li class="rs-line"><span class="rs-qty">{{quantity}} ×</span> <span class="rs-name">{{name}}</span> <span class="rs-policy">{{policy}}</span> <span class="rs-amount">{{amount}}</span></li>';
var TOTAL = '<div class="rs-total"><div class="rs-total-label">{{label}}</div><div class="rs-total-amount">{{amount}}</div><div class="rs-taxes">{{taxes}}</div></div>';

// Renders the reservation block next to the room table and the sticky price
// in the page header.
export var reservationSummary = {
    init: function ($container, config) {
        var self = this;
        this.$summary = $container.find("#rt-summary");
        this.$sticky = $container.find(".pp-sticky-price");
        this.$button = $container.find("#rt-reserve");
        this.config = config;
        jQuery(document).off("rooms:selection.summary").on("rooms:selection.summary", function (event, rows) {
            self.render(rows);
        });
    },

    render: function (rows) {
        var config = this.config;
        var strings = config.strings;
        var lines = [];
        var total = 0;
        var rooms = 0;
        var guests = 0;
        jQuery.each(jQuery.grep(rows, function (row) {
            return row.quantity > 0;
        }), function (i, row) {
            total += row.price * row.quantity;
            rooms += row.quantity;
            guests += row.occupancy * row.quantity;
            lines.push(template(LINE, { quantity: row.quantity, name: row.name, policy: row.policy === "flex" ? strings.flexible : strings.nonRefundable, amount: formatPrice(row.price * row.quantity, config.currencySymbol) }));
        });
        var html;
        if (rooms) {
            html = '<div class="rs-heading">' + strings.selected.replace("{count}", rooms) + "</div>"
                + '<ul class="rs-lines">' + lines.join("") + "</ul>"
                + template(TOTAL, { label: strings.total.replace("{nights}", config.nights), amount: formatPrice(total, config.currencySymbol), taxes: strings.taxes.replace("{amount}", formatPrice(total * 0.07 + 2.88 * config.nights * guests, config.currencySymbol)) })
                + '<p class="rs-redirect">' + strings.redirect + "</p>"
                + '<ul class="rs-benefits"><li>' + strings.confirmation + "</li><li>" + strings.noFees + "</li></ul>";
        } else {
            html = '<p class="rs-empty">' + strings.empty + "</p>";
        }
        this.$summary.html(html);
        this.$button.prop("disabled", rooms === 0).toggleClass("rt-reserve--active", rooms > 0).text(rooms ? strings.reserveCount.replace("{count}", rooms) : strings.reserve);
        this.$sticky.text(rooms ? formatPrice(total, config.currencySymbol) : this.$sticky.attr("data-from"));
    },
};
