// The property page's legacy scripts, in the style of a long-lived
// server-rendered page: jQuery 1.11 with modules that own the room table and
// the reservation summary. They run as one classic script, outside the
// micro-frontends, and boot when a property page is shown.
import jQuery from "jquery";
import "./property.css";
import { roomTable } from "./room-table.js";
import { reservationSummary } from "./reservation-summary.js";
import { priceTracking } from "./price-tracking.js";
import { upsell } from "./upsell.js";
import { pageChrome } from "./page-chrome.js";

window.jQuery = window.$ = jQuery;

var modules = [pageChrome, roomTable, reservationSummary, priceTracking, upsell];

window.TravelLegacy = {
    sink: [],
    boot: function (container) {
        var $container = jQuery(container);
        var config = jQuery.parseJSON($container.find("#legacy-config").text());
        jQuery(function () {
            jQuery.each(modules, function (i, module) {
                module.init($container, config);
            });
        });
    },
};
