import jQuery from "jquery";

// Suggests more rooms when the selection doesn't fit the travellers.
export var upsell = {
    init: function ($container, config) {
        var $hint = $container.find(".rt-upsell");
        jQuery(document).off("rooms:selection.upsell").on("rooms:selection.upsell", function (event, rows) {
            var capacity = 0;
            jQuery.each(rows, function (i, row) {
                capacity += row.occupancy * row.quantity;
            });
            var missing = config.adults - capacity;
            var cheapest = jQuery.grep(rows, function (row) {
                return row.quantity === 0;
            }).sort(function (a, b) {
                return a.price - b.price;
            })[0];
            if (capacity > 0 && missing > 0 && cheapest) {
                $hint.find(".rt-upsell-text").text(config.strings.upsell.replace("{count}", missing).replace("{room}", cheapest.name));
                $hint.show();
            } else {
                $hint.hide();
            }
        });
    },
};
