import jQuery from "jquery";
import { formatPrice } from "./format.js";

// Owns the quantity selects of the room table: keeps the rows' selected
// state, enforces the shared availability of each room type across its rate
// rows, and announces the selection to the other modules.
export var roomTable = {
    init: function ($container, config) {
        var $table = $container.find("#rooms-table");
        var self = this;
        this.config = config;
        this.$table = $table;
        $table.find("select.rt-qty").each(function () {
            var $select = jQuery(this);
            $select.data("initial", $select.val());
        });
        $table.on("change", "select.rt-qty", function (event) {
            self.onChange(jQuery(event.target));
        });
        $table.find("tr.rt-row").each(function (i) {
            jQuery(this).attr("data-row-index", i).toggleClass("rt-row--odd", i % 2 === 1);
        });
    },

    selection: function () {
        var rows = [];
        this.$table.find("tr.rt-row").each(function () {
            var $row = jQuery(this);
            var quantity = parseInt($row.find("select.rt-qty").val(), 10) || 0;
            rows.push({
                blockId: $row.attr("data-block-id"),
                roomId: $row.attr("data-room-id"),
                name: $row.attr("data-room-name"),
                price: parseFloat($row.attr("data-price")),
                occupancy: parseInt($row.attr("data-occupancy"), 10),
                quantity: quantity,
                policy: $row.attr("data-policy"),
            });
        });
        return rows;
    },

    enforceAvailability: function (rows) {
        var used = {};
        var config = this.config;
        jQuery.each(rows, function (i, row) {
            used[row.roomId] = (used[row.roomId] || 0) + row.quantity;
        });
        this.$table.find("tr.rt-row").each(function () {
            var $row = jQuery(this);
            var roomId = $row.attr("data-room-id");
            var $select = $row.find("select.rt-qty");
            var own = parseInt($select.val(), 10) || 0;
            var left = config.availability[roomId] - used[roomId] + own;
            $select.find("option").each(function () {
                var $option = jQuery(this);
                var disabled = parseInt($option.val(), 10) > left;
                if ($option.prop("disabled") !== disabled)
                    $option.prop("disabled", disabled);
            });
            $row.find(".rt-left").text(left <= 3 ? config.strings.onlyLeft.replace("{count}", left) : "");
        });
    },

    onChange: function ($select) {
        var rows = this.selection();
        var config = this.config;
        this.enforceAvailability(rows);
        this.$table.find("tr.rt-row").each(function (i) {
            var row = rows[i];
            var $row = jQuery(this);
            $row.toggleClass("rt-row--selected", row.quantity > 0);
            $row.find(".rt-price-total").html(row.quantity > 0 ? "<strong>" + formatPrice(row.price * row.quantity, config.currencySymbol) + "</strong>" : "");
        });
        $select.closest("tr").find(".rt-room-name").toggleClass("rt-room-name--active", parseInt($select.val(), 10) > 0);
        jQuery(document).trigger("rooms:selection", [rows]);
    },
};
